export function COCRDUP() {
  const [formData, setFormData] = useState({ cardsid: '' });
  const FUNCTION_KEYS = [{ key: 'Enter', action: 'ENTER' }, { key: 'F3', action: 'PF3' }];
  return (
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(80, 1ch)', gridTemplateRows: 'repeat(24, 1.35em)' }}>
      <span style={{ gridRow: 1, gridColumn: '1 / span 5' }}>{'Tran:'}</span>
      <span style={{ gridRow: 8, gridColumn: '23 / span 19' }}>{'Card Number       :'}</span>
      <input style={{ gridRow: 8, gridColumn: '45 / span 16' }} id="cardsid" maxLength={16} value={formData.cardsid} />
      <span style={{ gridRow: 24, gridColumn: '1 / span 21' }}>{'ENTER=Process F3=Exit'}</span>
    </div>
  );
}

export function BNK1ACC() {
  return (
    <div style={{ display: 'grid' }}>
      <span style={{ gridRow: 5, gridColumn: '10 / span 12' }}>{'Account No:'}</span>
      <input style={{ gridRow: 5, gridColumn: '25 / span 10' }} id="acctno" inputMode="numeric" maxLength={10} />
      <span style={{ gridRow: 7, gridColumn: '10 / span 9' }}>{'Password:'}</span>
      <input style={{ gridRow: 7, gridColumn: '25 / span 8' }} id="passwd" type="password" maxLength={8} />
      <span style={{ gridRow: 24, gridColumn: '1 / span 15' }}>{'ENTER=Submit'}</span>
    </div>
  );
}

